 "content": "def transform(grid):
    """Repeat the nonzero pattern attached to an end of a color-5 bar."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bars = []

    # Straight horizontal bars.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and g[r][c] == 5:
                c += 1
            if c - start >= 2:
                bars.append(("H", r, start, c - 1))

    # Straight vertical bars.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and g[r][c] == 5:
                r += 1
            if r - start >= 2:
                bars.append(("V", c, start, r - 1))

    for orient, fixed, lo, hi in bars:
        if orient == "V":
            c = fixed
            # Pattern is immediately to the right, bottom-aligned with the bar.
            x0 = c + 1
            if x0 >= w:
                continue
            bottom = hi
            y0 = bottom
            while y0 >= lo and any(g[y0][x] != 0 and g[y0][x] != 5 for x in range(x0, w)):
                y0 -= 1
            y0 += 1
            if y0 > bottom:
                continue
            # Width is the contiguous nonzero run adjacent to the bar.
            x1 = x0
            while x1 < w and g[bottom][x1] not in (0, 5):
                x1 += 1
            if x1 == x0:
                continue
            # Restrict pattern rows to cells nonzero throughout that width.
            while y0 < bottom and any(g[y0][x] in (0, 5) for x in range(x0, x1)):
                y0 += 1
            pattern = [row[x0:x1] for row in g[y0:bottom + 1]]
            if not pattern:
                continue
            for r in range(lo, hi + 1):
                src = pattern[(r - lo) % len(pattern)]
                for j, value in enumerate(src):
                    if c + 1 + j < w and g[r][c + 1 + j] == 0:
                        g[r][c + 1 + j] = value
        else:
            r = fixed
            # Pattern is immediately below, left-aligned with the bar.
            y0 = r + 1
            if y0 >= h:
                continue
            x = lo
            y1 = y0
            while y1 < h and g[y1][x] not in (0, 5):
                y1 += 1
            if y1 == y0:
                continue
            pattern = [g[y][x] for y in range(y0, y1)]
            for c in range(lo, hi + 1):
                for j, value in enumerate(pattern):
                    rr = y0 + j
                    if rr < h and g[rr][c] == 0:
                        g[rr][c] = value
    return g

